script:
html { scroll-behavior: smooth; }
::selection { background: #3E6DE8; color: #FFFFFF; }

html.en-js .en-rise { opacity: 0; transform: translateY(20px); }
html.en-js .en-rise.en-in {
  opacity: 1; transform: none;
  transition: opacity 0.85s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.85s cubic-bezier(0.22, 1, 0.36, 1);
}
html.en-js .en-d1.en-in { transition-delay: 0.12s; }
html.en-js .en-d2.en-in { transition-delay: 0.24s; }

.en-grow { flex-grow: 1; flex-shrink: 1; min-width: 0; }

.en-ul {
  background-image: linear-gradient(currentColor, currentColor);
  background-position: left bottom; background-repeat: no-repeat;
  background-size: 0% 1.5px;
  transition: background-size 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}
.en-ul:hover { background-size: 100% 1.5px; }

.en-btn { transition: transform 0.25s ease, box-shadow 0.25s ease,
  background-color 0.25s ease; }
.en-btn:hover { background-color: #2F5BD1; transform: translateY(-2px);
  box-shadow: 0 12px 26px rgba(62, 109, 232, 0.35); }
.en-btn-o { transition: border-color 0.25s ease, transform 0.25s ease,
  background-color 0.25s ease; }
.en-btn-o:hover { background-color: #FFFFFF; border-color: #3E6DE8;
  transform: translateY(-2px); }
.en-btn-w { transition: transform 0.25s ease, box-shadow 0.25s ease; }
.en-btn-w:hover { transform: translateY(-2px);
  box-shadow: 0 12px 26px rgba(23, 34, 64, 0.3); }
.en-btn-b { transition: background-color 0.25s ease, transform 0.25s ease; }
.en-btn-b:hover { background-color: rgba(255, 255, 255, 0.12);
  transform: translateY(-2px); }

.en-card { transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
  box-shadow 0.35s ease; }
.en-card:hover { transform: translateY(-4px);
  box-shadow: 0 18px 44px rgba(43, 38, 32, 0.09); }

html.en-js .en-blob { border-radius: 58% 42% 55% 45% / 48% 54% 46% 52%;
  animation: en-morph 14s ease-in-out infinite alternate; }
@keyframes en-morph {
  0% { border-radius: 58% 42% 55% 45% / 48% 54% 46% 52%; }
  50% { border-radius: 45% 55% 48% 52% / 55% 44% 56% 45%; }
  100% { border-radius: 52% 48% 42% 58% / 46% 55% 45% 54%; }
}

html.en-js .en-float { animation: en-bob 5.5s ease-in-out infinite; }
html.en-js .en-float-2 { animation-delay: -2.7s; }
@keyframes en-bob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-9px); }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  html.en-js .en-blob, html.en-js .en-float { animation: none; }
}
